(7353126, 1150523, 49954, '<td valign="top">First 10 commenting: seems a little out of focus.  Composition too is a bit busy.</td>', 'First 10 commenting: seems a little out of focus.  Composition too is a bit busy.', '2015-05-25 11:59:54.000000', NULL, 1),
(7353128, 1150439, 49954, '<td valign="top">First 10 commenting: Wish the landscape were a little more prominent instead of just being a backdrop.  Great image in general though...</td>', 'First 10 commenting: Wish the landscape were a little more prominent instead of just being a backdrop.  Great image in general though...', '2015-05-25 12:00:30.000000', NULL, 1),
(7353129, 1150658, 49954, '<td valign="top">First 10 commenting: Not keen on the processing, just a bit gritty.  The island on the right tailing off the screen is a distraction too...</td>', 'First 10 commenting: Not keen on the processing, just a bit gritty.  The island on the right tailing off the screen is a distraction too...', '2015-05-25 12:01:10.000000', NULL, 1),
(7353132, 1150616, 49954, '<td valign="top">First 10 commenting: Bet a lot of fish hang around that stump...</td>', 'First 10 commenting: Bet a lot of fish hang around that stump...', '2015-05-25 12:01:46.000000', NULL, 1),
(7353134, 1150475, 49954, '<td valign="top">First 10 commenting: Color is a bit flat, perhaps a contrast boost would help, especially in the sky.  Lovely subject matter though, nice greens.  However the fence leading us into the shot, leads us right out of the shot on the right.</td>', 'First 10 commenting: Color is a bit flat, perhaps a contrast boost would help, especially in the sky.  Lovely subject matter though, nice greens.  However the fence leading us into the shot, leads us right out of the shot on the right.', '2015-05-25 12:02:43.000000', NULL, 1),
(7353135, 1150639, 49954, '<td valign="top">First 10 commenting: Nice drama in the skies, but the overall composition is a bit off.  I think if you''d been 10 step forward, reducing the impact of that left scraggly tree it might have been better.</td>', 'First 10 commenting: Nice drama in the skies, but the overall composition is a bit off.  I think if you''d been 10 step forward, reducing the impact of that left scraggly tree it might have been better.', '2015-05-25 12:03:50.000000', NULL, 1),
(7353136, 1150657, 49954, '<td valign="top">First 10 commenting: Photo of a bird an dragonflies (damselflies?)  the landscape appears very secondary in this one</td>', 'First 10 commenting: Photo of a bird an dragonflies (damselflies?)  the landscape appears very secondary in this one', '2015-05-25 12:04:27.000000', NULL, 1),
(7353138, 1150636, 49954, '<td valign="top">First 10 commenting: The trees chopped off is distracting, as it looks like we just barely don''t get them all in frame.  A lower POV so we''re looking through the opening/gate could have helped.</td>', 'First 10 commenting: The trees chopped off is distracting, as it looks like we just barely don''t get them all in frame.  A lower POV so we''re looking through the opening/gate could have helped.', '2015-05-25 12:05:39.000000', NULL, 1),
(7353139, 1150280, 49954, '<td valign="top">First 10 commenting: Not a lot of effort here, IMO.  Seems like a quick snapshot vs. a planned landscape.  Too many distracting elements as well.</td>', 'First 10 commenting: Not a lot of effort here, IMO.  Seems like a quick snapshot vs. a planned landscape.  Too many distracting elements as well.', '2015-05-25 12:06:42.000000', NULL, 1),
(7353140, 1150631, 49954, '<td valign="top">First 10 commenting: Nice shot of a rocket launch, but that steals the scene from the landscape, which is secondary to the shot.</td>', 'First 10 commenting: Nice shot of a rocket launch, but that steals the scene from the landscape, which is secondary to the shot.', '2015-05-25 12:07:43.000000', NULL, 1),
(7353146, 1150509, 115814, '<td valign="top">Such a standout in the challenge. Lovely color palette and exposure supporting a beautifully layered and composed scene. My top pick!</td>', 'Such a standout in the challenge. Lovely color palette and exposure supporting a beautifully layered and composed scene. My top pick!', '2015-05-25 12:30:58.000000', NULL, 1),
(7353147, 1150511, 115814, '<td valign="top">Literal and deceivingly abstract at the same time. Very nice!</td>', 'Literal and deceivingly abstract at the same time. Very nice!', '2015-05-25 12:32:15.000000', NULL, 1),
(7353148, 1150627, 115814, '<td valign="top">Thank you for not over-saturating.  A terrific result without attempting to reinvent the natural quality of light and color. A top pick from me.</td>', 'Thank you for not over-saturating.  A terrific result without attempting to reinvent the natural quality of light and color. A top pick from me.', '2015-05-25 12:34:45.000000', NULL, 1),
