(7353156, 1150478, 100393, '<td valign="top">Brilliant. Dark, slightly ominous but uplifting too. Life, textured. Bravo (and a 10).</td>', 'Brilliant. Dark, slightly ominous but uplifting too. Life, textured. Bravo (and a 10).', '2015-05-25 13:02:50.000000', NULL, 1),
(7353201, 1150590, 77185, '<td valign="top">The blow out/banded sky is distracting, but those rocky textures are gorgeous!</td>', 'The blow out/banded sky is distracting, but those rocky textures are gorgeous!', '2015-05-25 16:41:29.000000', NULL, 1),
(7353203, 1150670, 77185, '<td valign="top">I''d be a happy valley too, with that view. :) Nice point of view!</td>', 'I''d be a happy valley too, with that view. :) Nice point of view!', '2015-05-25 16:42:13.000000', NULL, 1),
(7353204, 1150607, 77185, '<td valign="top">It feels slightly unbalanced, as if my eyes shy away from the clutter on the right and wants to rest on the calmer part on the left. Then again, without the right side the picture would be boring, so I find myself looking back to the right. Very interesting!</td>', 'It feels slightly unbalanced, as if my eyes shy away from the clutter on the right and wants to rest on the calmer part on the left. Then again, without the right side the picture would be boring, so I find myself looking back to the right. Very interesting!', '2015-05-25 16:49:02.000000', NULL, 1),
(7353214, 1150588, 123833, '<td valign="top">A very green meadow! ;)</td>', 'A very green meadow! ;)', '2015-05-25 17:34:00.000000', NULL, 1),
(7353215, 1150476, 123833, '<td valign="top">It would be nice if it were in focus</td>', 'It would be nice if it were in focus', '2015-05-25 17:42:12.000000', NULL, 1),
