(7353217, 1150511, 123833, '<td valign="top">Great architecture shot</td>', 'Great architecture shot', '2015-05-25 17:45:18.000000', NULL, 1),
(7353218, 1150581, 123833, '<td valign="top">The better of the two similar images</td>', 'The better of the two similar images', '2015-05-25 17:45:47.000000', NULL, 1),
