(7355517, 1150554, 62249, '<td valign="top">The title needs work ;-). Very nice take on the Bay Bridge &amp; SF. The sky above the bridge is over processed. But the composition is lovely.</td>', 'The title needs work ;-). Very nice take on the Bay Bridge & SF. The sky above the bridge is over processed. But the composition is lovely.', '2015-05-31 20:18:48.000000', NULL, 1),
(7355518, 1150597, 62249, '<td valign="top">I really like how the motion of the boats gives this image a painterly feel. Very nice.</td>', 'I really like how the motion of the boats gives this image a painterly feel. Very nice.', '2015-05-31 20:19:26.000000', NULL, 1),
(7355519, 1150590, 62249, '<td valign="top">Too much banding in the upper left corner, but lots of good texture and tonal range in the rest of the scene.</td>', 'Too much banding in the upper left corner, but lots of good texture and tonal range in the rest of the scene.', '2015-05-31 20:20:43.000000', NULL, 1),
(7355520, 1150646, 62249, '<td valign="top">I like the composition a lot. Too much sharpening, though. It left a very visible halo along the top edge of the land where it meets the sky.</td>', 'I like the composition a lot. Too much sharpening, though. It left a very visible halo along the top edge of the land where it meets the sky.', '2015-05-31 20:22:05.000000', NULL, 1),
(7355522, 1150630, 62249, '<td valign="top">The contrasty processing works really well on the grass, benches, walkway, water, and trees. Not so much on the clouds. Composition is good.</td>', 'The contrasty processing works really well on the grass, benches, walkway, water, and trees. Not so much on the clouds. Composition is good.', '2015-05-31 20:24:48.000000', NULL, 1),
(7355524, 1150523, 62249, '<td valign="top">There''s not really much of a subject in this shot. Just lots of greenery without any obvious compositional intent. Maybe if there were an obviously visible fox in the frame?</td>', 'There''s not really much of a subject in this shot. Just lots of greenery without any obvious compositional intent. Maybe if there were an obviously visible fox in the frame?', '2015-05-31 20:27:38.000000', NULL, 1),
(7355526, 1150636, 62249, '<td valign="top">The fence sections and three trees are nice elements in the scene. The overprocessing detracts from image. Do less HDR so you don''t end up with odd black blotches in the pine needs.</td>', 'The fence sections and three trees are nice elements in the scene. The overprocessing detracts from image. Do less HDR so you don''t end up with odd black blotches in the pine needs.', '2015-05-31 20:31:22.000000', NULL, 1),
