(7355678, 1150675, 119419, '<td valign="top">That''s a wow!</td>', 'That''s a wow!', '2015-06-01 01:14:30.000000', NULL, 0),
(7355682, 1150554, 14476, '<td valign="top">well, okay!  didn''t know this was yours, Brennan, but was puzzled as to what the photographer''s vantage point was for this one.<br/> <br/>Lovely composition and yes, those star lights are perfect.</td>', 'well, okay!  didn''t know this was yours, Brennan, but was puzzled as to what the photographer''s vantage point was for this one. Lovely composition and yes, those star lights are perfect.', '2015-06-01 01:16:38.000000', NULL, 0),
(7355689, 1150568, 16106, '<td valign="top">Great tone, but there is no center here. Well it is there, in the pond, behind, but it is hidden away by branches. My eye just roves around and around up the trees, across the horizon seeking something to settle on.</td>', 'Great tone, but there is no center here. Well it is there, in the pond, behind, but it is hidden away by branches. My eye just roves around and around up the trees, across the horizon seeking something to settle on.', '2015-06-01 01:20:37.000000', NULL, 0),
(7355698, 1150375, 16106, '<td valign="top">The bouy, or sail on the left really nails this one down. One of my pick. I love the way the reflections and the sky mirror each other.</td>', 'The bouy, or sail on the left really nails this one down. One of my pick. I love the way the reflections and the sky mirror each other.', '2015-06-01 01:23:36.000000', NULL, 0),
(7355702, 1150571, 16106, '<td valign="top">Subtle, understated, elegant. I think if the central tower was not so centered it would have been stronger, but The rest of the composition would have been hurt by reframing.</td>', 'Subtle, understated, elegant. I think if the central tower was not so centered it would have been stronger, but The rest of the composition would have been hurt by reframing.', '2015-06-01 01:29:07.000000', NULL, 0),
(7355716, 1150626, 62357, '<td valign="top">Congratulations on  fabulous image. 9 from me. This ticks all the boxes as far as I am concerned. I see you got a <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21_N.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21_N.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21_N.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=30364" rel="nofollow" target="_blank">Ubique</a>order of the thumb:) how fab.</td>', 'Congratulations on  fabulous image. 9 from me. This ticks all the boxes as far as I am concerned. I see you got a  Ubiqueorder of the thumb:) how fab.', '2015-06-01 01:36:01.000000', NULL, 0),
(7355719, 1150675, 68504, '<td valign="top">wicked.</td>', 'wicked.', '2015-06-01 01:38:45.000000', NULL, 0),
(7355720, 1150489, 16106, '<td valign="top">A lovely image, but perhaps a bit too blue? had those first few ranges been green and the a fade to blue in the distance this would have read more true to me.</td>', 'A lovely image, but perhaps a bit too blue? had those first few ranges been green and the a fade to blue in the distance this would have read more true to me.', '2015-06-01 01:39:28.000000', NULL, 0),
