INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7355726, 1150382, 68504, '<td valign="top">beautiful.</td>', 'beautiful.', '2015-06-01 01:44:34.000000', NULL, 0),
(7355728, 1150548, 68504, '<td valign="top">no comments? whizzing through the entries without voting I wanted to say something about those lovely vertical brush strokes!</td>', 'no comments? whizzing through the entries without voting I wanted to say something about those lovely vertical brush strokes!', '2015-06-01 01:46:18.000000', NULL, 0),
(7355730, 1150675, 30364, '<td valign="top">It''s OK.  The flowers and trees and clouds are a bit distracting, the rest of it''s quite good though.</td>', 'It''s OK.  The flowers and trees and clouds are a bit distracting, the rest of it''s quite good though.', '2015-06-01 01:47:13.000000', NULL, 0),
(7355731, 1150478, 68504, '<td valign="top">funny looking elephant. and that is a beautiful display of votes.<br/><br/><i>Message edited by author 2015-06-01 00:48:59.</i></td>', 'funny looking elephant. and that is a beautiful display of votes.', '2015-06-01 01:48:05.000000', '2015-06-01 01:48:59.000000', 0),
(7355733, 1150616, 16106, '<td valign="top">I think there is so much here, but a stronger edit to really make that stump the star of the show was called for. It is a nicely framed shot and there are fabulous textures here, but they are speaking very softly.</td>', 'I think there is so much here, but a stronger edit to really make that stump the star of the show was called for. It is a nicely framed shot and there are fabulous textures here, but they are speaking very softly.', '2015-06-01 01:49:36.000000', NULL, 0),
(7355734, 1150626, 68504, '<td valign="top">much deserved blue thumb.</td>', 'much deserved blue thumb.', '2015-06-01 01:51:36.000000', NULL, 0),
(7355735, 1150626, 30364, '<td valign="top">Oops, I said I gave you a 10 and I see it was only a 9, because I forgot to do that final bump.  Sorry about that, I will give you an 11 next time, and say it was 10.  Still love the picture.</td>', 'Oops, I said I gave you a 10 and I see it was only a 9, because I forgot to do that final bump.  Sorry about that, I will give you an 11 next time, and say it was 10.  Still love the picture.', '2015-06-01 01:52:33.000000', NULL, 0),
(7355736, 1150511, 68504, '<td valign="top">extraordinary.</td>', 'extraordinary.', '2015-06-01 01:52:33.000000', NULL, 0),
(7355737, 1150645, 68504, '<td valign="top">what Paul said.</td>', 'what Paul said.', '2015-06-01 01:58:08.000000', NULL, 0),
(7355740, 1150478, 16106, '<td valign="top">I always like to comment on the shot that had the greatest shift between my top scoring group and a less august placement, and my friend, why am I not surprised to find you there. The startled focus of the giraffe among the chaotic wash of the vegetation is lovely. Congratulations, and commiserations.</td>', 'I always like to comment on the shot that had the greatest shift between my top scoring group and a less august placement, and my friend, why am I not surprised to find you there. The startled focus of the giraffe among the chaotic wash of the vegetation is lovely. Congratulations, and commiserations.', '2015-06-01 01:59:31.000000', NULL, 0),
(7355741, 1150478, 62357, '<td valign="top">Fabulous image and one of my top scoring.  Interesting vote distribution.</td>', 'Fabulous image and one of my top scoring.  Interesting vote distribution.', '2015-06-01 02:06:34.000000', NULL, 0),
(7355742, 1150580, 16106, '<td valign="top">Everything you presented us with here is lovely, but there is so much of everything that my eye does not know where to go. Having so much action on the middle of the image, with nothing but empty grass in the foreground makes me feel like I filled up on boring appetizers before a great main course and salad were served and there s no room for desert and cofee. Had you landed a cow, a lovely flower, or even an interesting clump of grass in the right foreground, I feel this would have been close to the ribbons.<br/>As Robert Capa once said, If your pictures arent good enough, youre not close enough. And I think that applies here, there is so much wonderful stuff here, and the editing is top-notch, just move closer.</td>', 'Everything you presented us with here is lovely, but there is so much of everything that my eye does not know where to go. Having so much action on the middle of the image, with nothing but empty grass in the foreground makes me feel like I filled up on boring appetizers before a great main course and salad were served and there s no room for desert and cofee. Had you landed a cow, a lovely flower, or even an interesting clump of grass in the right foreground, I feel this would have been close to the ribbons.As Robert Capa once said, If your pictures arent good enough, youre not close enough. And I think that applies here, there is so much wonderful stuff here, and the editing is top-notch, just move closer.', '2015-06-01 02:10:10.000000', NULL, 0),
(7355743, 1150638, 16106, '<td valign="top">As Wejna said "when we got there, there was no there, there". It may have been Stein who said it, whatever. There are some great elements here, but nothing for the gaze to linger on.</td>', 'As Wejna said "when we got there, there was no there, there". It may have been Stein who said it, whatever. There are some great elements here, but nothing for the gaze to linger on.', '2015-06-01 02:14:21.000000', NULL, 0),
(7355745, 1150663, 16106, '<td valign="top">I am surprised this did not finish higher, because there are so many nice elements here, but they seem to add up to less than their parts for reasons I am not sure of. Perhaps the whole frame is so filled with action, it lacks the calm that I am seeking in a landscape. I feel I should like this more than I do. I wish I could tell you why.</td>', 'I am surprised this did not finish higher, because there are so many nice elements here, but they seem to add up to less than their parts for reasons I am not sure of. Perhaps the whole frame is so filled with action, it lacks the calm that I am seeking in a landscape. I feel I should like this more than I do. I wish I could tell you why.', '2015-06-01 02:19:19.000000', NULL, 0),
(7355747, 1150642, 16106, '<td valign="top">I find the noise in the sky distracting, the cramped horizon and the speckled sky do not add to the lovely tones and backlight in the grasses, and the perfect placement of the flowers. Those are the simple things, but for me, their presentation was over complicated.</td>', 'I find the noise in the sky distracting, the cramped horizon and the speckled sky do not add to the lovely tones and backlight in the grasses, and the perfect placement of the flowers. Those are the simple things, but for me, their presentation was over complicated.', '2015-06-01 02:24:14.000000', NULL, 0),
(7355748, 1150632, 16106, '<td valign="top">Those two strong sheaves of grass at each side, the tree on one hand and the sun on the other, create so much tension on the edges of the image that they keep pulling my eye way from a pretty nice landscape in the middle.</td>', 'Those two strong sheaves of grass at each side, the tree on one hand and the sun on the other, create so much tension on the edges of the image that they keep pulling my eye way from a pretty nice landscape in the middle.', '2015-06-01 02:29:33.000000', NULL, 0),
(7355749, 1150652, 16106, '<td valign="top">The sky is lovely, and the placement of the tree as if it were drawing in the clouds is ideal, but there is something about the greens that feels off. Perhaps a wider frame with more grass? I don''t know but the bottom feel like it is over pressurized somehow.</td>', 'The sky is lovely, and the placement of the tree as if it were drawing in the clouds is ideal, but there is something about the greens that feels off. Perhaps a wider frame with more grass? I don''t know but the bottom feel like it is over pressurized somehow.', '2015-06-01 02:34:00.000000', NULL, 0),
(7355758, 1150645, 30982, '<td valign="top">I didn''t vote this time but I did look at each entry and this was my favorite.</td>', 'I didn''t vote this time but I did look at each entry and this was my favorite.', '2015-06-01 03:31:22.000000', NULL, 0),
