(7355772, 1150658, 61396, '<td valign="top"><a href="//www.dpchallenge.com/image.php?IMAGE_ID=1007775" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_challenge/1000-1999/1550/120/Copyrighted_Image_Reuse_Prohibited_1007775.jpg'', strrpos(''//images.dpchallenge.com/images_challenge/1000-1999/1550/120/Copyrighted_Image_Reuse_Prohibited_1007775.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_challenge/1000-1999/1550/120/Copyrighted_Image_Reuse_Prohibited_1007775.jpg"/></a></td>', '', '2015-06-01 04:56:33.000000', NULL, 0),
